import {form,field,number as num,select as sel,text,area,result,outputText,e,n,bytes,error} from '../ui.mjs';
import {secureIndex} from '../core.mjs';
import {uploadHTML,bindUpload} from '../media.mjs';
import {certificateDER,policySource,inspectURL,inspectCertificate} from './security-core.mjs';
import {need,optional,table,textFile} from './shared.mjs';
export function setupSecurity(tool,mount,out){const id=tool.id;if(id==='file-checksum')return checksum(mount,out);if(id==='certificate-viewer')return certificate(mount,out);if(id==='passphrase')return passphrases(mount,out);if(id==='url-inspector'){form(mount,[text('url','URL to inspect','https://example.com/path?source=nepocore#section','url',true)],v=>{const r=inspectURL(v.url);result(out,{label:'Actual hostname',value:r.hostname,details:[['Protocol',r.protocol],['Port',r.port],['Path',r.pathname],['Fragment',r.fragment||'(none)'],['Username',r.username],['Password',r.password]],html:'<h3>Structural observations</h3><ul>'+r.flags.map(x=>'<li>'+e(x)+'</li>').join('')+'</ul>'+table(['Query parameter','Value'],r.query),copy:JSON.stringify(r,null,2),note:'This tool does not open the URL or check a live reputation database. A valid-looking URL can still be unsafe.'});},{label:'Inspect URL structure'});return;}if(id==='csp-builder'){form(mount,[sel('mode','Header mode',[['report','Report-only while testing'],['enforce','Enforce policy']],'report'),text('script','script-src',"'self'",'text',true),text('style','style-src',"'self'",'text',true),text('images','img-src',"'self' data:",'text',true),text('font','font-src',"'self'",'text',true),text('connect','connect-src',"'self'",'text',true),text('frames','frame-src',"'none'",'text',true)],v=>{const directives=["default-src 'none'",'script-src '+policySource(v.script),'style-src '+policySource(v.style),'img-src '+policySource(v.images),'font-src '+policySource(v.font),'connect-src '+policySource(v.connect),'frame-src '+policySource(v.frames),"object-src 'none'","base-uri 'self'","frame-ancestors 'none'","form-action 'self'"],header=(v.mode==='report'?'Content-Security-Policy-Report-Only':'Content-Security-Policy')+': '+directives.join('; ');textFile(out,header+'\n','nepocore-csp-header.txt');out.insertAdjacentHTML('beforeend','<p class="form-note">Deploy as an HTTP response header and test your application. Report-only requires a configured reporting endpoint if you want collected reports. This generator does not add one.</p>');},{label:'Build CSP header',note:'Enter your actual origins. Nonces must be generated per response; do not reuse an example nonce as a permanent secret.'});return;}throw Error('This security tool is unavailable.');}
function passphrases(mount,out){let disposed=false;form(mount,[num('count','Words per passphrase',6,4,12,1),sel('separator','Word separator',[['-','Hyphen'],[' ','Space'],['_','Underscore']],'-'),sel('case','Letter case',[['lower','Lowercase'],['title','Capitalize words']],'lower'),sel('number','Append a random number',[['no','No'],['yes','Yes, four digits']],'no')],async v=>{const {words}=await import('../assets/vendor/eff-words.mjs');if(disposed)return;const selected=Array.from({length:+v.count},()=>words[secureIndex(words.length)]),phrase=selected.map(w=>v.case==='title'?w[0].toUpperCase()+w.slice(1):w).join(v.separator)+(v.number==='yes'?v.separator+String(secureIndex(10000)).padStart(4,'0'):'');outputText(out,phrase,[['Random word-list size',words.length],['Word-choice entropy',n(+v.count*Math.log2(words.length))+' bits'],['Random source','Browser cryptographic generator']]);},{label:'Generate passphrase',note:'Entropy describes independent uniform word selection only. Keep the result private; generated phrases are not stored.'});return()=>{disposed=true;};}
function checksum(mount,out){let file,worker,disposed=false;mount.innerHTML='<h2>Check the bytes, locally</h2>'+uploadHTML('*/*',false,'Choose a file to hash','Any file · up to 200 MB · streamed in a worker')+'<p class="file-info form-note"></p><form><div class="form-grid">'+[sel('algorithm','Algorithm',['SHA-256','SHA-512'],'SHA-256'),optional(text('expected','Expected hash (optional)','','text',true))].map(field).join('')+'</div><button class="btn primary" type="submit" disabled>Calculate & compare</button><p class="hash-progress form-note"></p><div class="form-error"></div></form>';const f=mount.querySelector('form'),b=f.querySelector('button'),err=f.querySelector('.form-error'),progress=f.querySelector('.hash-progress');bindUpload(mount,files=>{try{need(files[0]&&files[0].size<=200*1024*1024,'Choose a file up to 200 MB.');file=files[0];mount.querySelector('.file-info').textContent=file.name+' · '+bytes(file.size);b.disabled=false;err.innerHTML='';}catch(ex){error(err,ex.message);}});f.onsubmit=async ev=>{ev.preventDefault();if(!file||!f.reportValidity())return;b.disabled=true;err.innerHTML='';try{const v=Object.fromEntries(new FormData(f)),expected=v.expected.trim().toLowerCase().replace(/\s/g,'');need(!expected||new RegExp('^[a-f0-9]{'+(v.algorithm==='SHA-512'?128:64)+'}$').test(expected),'Expected hash must be a complete hexadecimal digest for the selected algorithm.');progress.textContent='Hashing…';worker=new Worker(new URL('./hash-worker.mjs',import.meta.url),{type:'module'});const digest=await new Promise((resolve,reject)=>{worker.onmessage=ev=>{if(ev.data.progress!==undefined){progress.textContent='Hashed '+bytes(ev.data.progress)+' of '+bytes(file.size);return;}ev.data.error?reject(Error(ev.data.error)):resolve(ev.data.digest);};worker.onerror=ev=>reject(Error(ev.message||'Hash worker failed.'));worker.postMessage({file,algorithm:v.algorithm});});worker.terminate();worker=null;if(disposed)return;outputText(out,digest,[['Algorithm',v.algorithm],['File',file.name],['Comparison',expected?(expected===digest?'MATCH — bytes agree with supplied digest':'DOES NOT MATCH'):'No reference supplied']]);progress.textContent='Complete. No file content was uploaded.';}catch(ex){worker?.terminate();worker=null;if(!disposed)error(err,ex.message);}finally{if(!disposed)b.disabled=false;}};return()=>{disposed=true;worker?.terminate();};}
function certificate(mount,out){let disposed=false;const f=form(mount,[area('pem','One public PEM certificate','','-----BEGIN CERTIFICATE-----\n…\n-----END CERTIFICATE-----')],async v=>{const info=await inspectCertificate(v.pem);if(disposed)return;const now=new Date();result(out,{label:'Parsed subject',value:info.subject,details:[['Issuer',info.issuer],['Serial number',info.serialNumber],['Not before',info.notBefore],['Not after',info.notAfter],['Date window only',now<new Date(info.notBefore)?'Not yet valid by dates':now>new Date(info.notAfter)?'Expired by dates':'Current date is within validity window'],['Public key algorithm',JSON.stringify(info.algorithm)],['SHA-256 fingerprint',info.fingerprint]],html:table(['Alternative name type','Value'],info.san.map(x=>[x.type,x.value])),copy:JSON.stringify(info,null,2),note:'Parsing and date display only. Trust chain, revocation, signature authenticity and hostname ownership have not been verified.'});},{label:'Inspect public certificate',auto:false,note:'Public certificates only. Do not paste private keys. No data is uploaded.'});mount.querySelector('h2').insertAdjacentHTML('afterend',uploadHTML('.pem,.crt,.cer,application/pkix-cert',false,'Or choose a certificate file','One PEM or DER public certificate · up to 256 KB'));bindUpload(mount,async files=>{try{need(files[0]&&files[0].size<=256*1024,'Choose a public certificate up to 256 KB.');const raw=new Uint8Array(await files[0].arrayBuffer()),s=new TextDecoder().decode(raw);let value=s;if(!s.includes('-----BEGIN CERTIFICATE-----')){let binary='';for(let i=0;i<raw.length;i+=8192)binary+=String.fromCharCode(...raw.slice(i,i+8192));value='-----BEGIN CERTIFICATE-----\n'+btoa(binary).match(/.{1,64}/g).join('\n')+'\n-----END CERTIFICATE-----';}f.elements.pem.value=value;f.requestSubmit();}catch(ex){error(f.querySelector('.form-error'),ex.message);}});return()=>{disposed=true;};}
